import React, { useState, useEffect } from "react";
import "bootstrap/dist/css/bootstrap.min.css";
import axios from "axios";

const Aula = () => {
  const [aulas, setAulas] = useState([]);
  const [materiais, setMateriais] = useState([]);
  const [curso, setCurso] = useState(null);

  // Carregar dados do curso, aulas e materiais
  useEffect(() => {
    const carregarDados = async () => {
      try {
        // Supondo que o aluno está matriculado em um curso
        const alunoResponse = await axios.get("/api/alunos/me"); // Você precisará criar esta rota
        const cursoId = alunoResponse.data.cursoId;

        if (cursoId) {
          const [cursoResponse, aulasResponse, materiaisResponse] =
            await Promise.all([
              axios.get(`/api/cursos/${cursoId}`),
              axios.get(`/api/aulas/curso/${cursoId}`),
              axios.get(`/api/materiais/curso/${cursoId}`),
            ]);

          setCurso(cursoResponse.data);
          setAulas(aulasResponse.data);
          setMateriais(materiaisResponse.data);
        }
      } catch (error) {
        console.error("Erro ao carregar dados:", error);
      }
    };

    carregarDados();
  }, []);

  return (
    <div
      className="container-fluid d-flex flex-column align-items-center"
      style={{
        backgroundColor: "#E7EFF4",
        minHeight: "100vh",
        padding: "20px",
      }}
    >
      <nav className="nav nav-tabs mb-3 bg-white p-2 w-75 d-flex justify-content-center">
        <a
          className="nav-link mx-3"
          href=""
          onClick={() => navigate(`/listacurso/${id}`)}
        >
          Cursos
        </a>
        <a className="nav-link" href="#">
          Aulas
        </a>
        <a
          className="nav-link mx-3"
          href=""
          onClick={() => navigate(`/avaliacao/${id}`)}
        >
          Avaliações
        </a>
      </nav>

      <h2 className="mb-3 text-center">Aulas {curso && `- ${curso.nome}`}</h2>
      <div className="row w-75">
        <div className="col-md-6 text-center">
          <h4>Aulas Ao Vivo</h4>
          <div className="bg-white p-3 rounded shadow">
            <img
              src="./live_class_placeholder.png"
              alt="Aula Ao Vivo"
              className="img-fluid"
            />
            <button className="btn btn-primary mt-2">Entrar</button>
          </div>
        </div>
        <div className="col-md-6">
          <h4>Aulas Gravadas</h4>
          <div className="list-group">
            {aulas.map((aula) => (
              <a
                key={aula.id}
                href={aula.videoUrl}
                target="_blank"
                rel="noopener noreferrer"
                className="list-group-item list-group-item-action"
              >
                {aula.titulo}
              </a>
            ))}
          </div>
        </div>
      </div>
      <div className="mt-4 text-center w-75">
        <div className="bg-white p-3 rounded shadow">
          <h4>Material de Apoio</h4>
          <div className="list-group">
            {materiais.map((material) => (
              <a
                key={material.id}
                href={material.arquivoUrl}
                target="_blank"
                rel="noopener noreferrer"
                className="list-group-item list-group-item-action"
              >
                {material.nome}
              </a>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Aula;
